const crypto = require('crypto');
// The secret Moniepoint shows you once when you create the webhook subscription. One per merchant.
const SECRET = 'YOUR_SUBSCRIPTION_SECRET';

const item = $input.first().json;
const h = item.headers || {};
const id = h['moniepoint-webhook-id'];
const ts = h['moniepoint-webhook-timestamp'];
const sig = h['moniepoint-webhook-signature'];
const body = JSON.stringify(item.body);

const expected = crypto
  .createHmac('sha256', SECRET)
  .update(`${id}__${ts}__${body}`)
  .digest('base64');

return [{ json: { valid: expected === sig, id, ts, receivedSig: sig, expectedSig: expected, body: item.body } }];

// Settings for this client
const SECURITY_WORD = '';

const d = $input.first().json;
if (!d.valid) throw new Error('Signature check failed: message did not come from Moniepoint');

const ev = d.body || {};
const t = ev.data || {};
const type = ev.eventType;

function naira(kobo) {
  const [whole, frac] = (Number(kobo) / 100).toFixed(2).split('.');
  return whole.replace(/\B(?=(\d{3})+(?!\d))/g, ',') + (frac === '00' ? '' : '.' + frac);
}

function clock(s) {
  const m = String(s || '').match(/(\d{2}):(\d{2})/);
  if (!m) return '';
  let h = Number(m[1]);
  const ap = h >= 12 ? 'PM' : 'AM';
  h = h % 12 || 12;
  return h + ':' + m[2] + ' ' + ap;
}

function finish(lines) {
  if (SECURITY_WORD) lines.push('Security word: ' + SECURITY_WORD);
  lines.push('', '_~YourBrand_');
  return [{ json: { text: lines.join('\n') } }];
}

if (type === 'V1_POS_TRANSFER_TRANSACTION') {
  // Only completed and approved transactions ever produce an alert
  if (t.transactionStatus !== 'COMPLETED' || t.responseMessage !== 'APPROVED') return [];
  let meta = {};
  try { meta = JSON.parse(t.metaData || '{}'); } catch (e) {}
  let name = String(meta.customerName || 'a customer').trim();
  if (name.includes(',')) {
    const p = name.split(',').map(s => s.trim());
    name = p.slice(1).join(' ') + ' ' + p[0];
  }
  name = name.toLowerCase().replace(/\b\w/g, c => c.toUpperCase());
  const ref = String(t.transactionReference || '').split('|').pop().slice(-6);
  const lines = ['✅ *Payment confirmed*', '', '*₦' + naira(t.amount) + '* from *' + name + '* has landed in your account.'];
  const when = clock(t.transactionTime);
  if (when) lines.push('Time: ' + when);
  lines.push('Ref: ' + ref);
  return finish(lines);
}

if (type === 'V1_POS_PURCHASE_TRANSACTION') {
  if (t.transactionStatus !== 'SUCCESSFUL' || t.responseCode !== '00') return [];
  const rrn = String(t.retrievalReferenceNumber || '').replace(/^0+/, '');
  const lines = ['✅ *Card payment approved*', '', '*₦' + naira(t.amount) + '* was approved on your terminal.'];
  const when = clock(t.transactionTime);
  if (when) lines.push('Time: ' + when);
  if (rrn) lines.push('Ref: ' + rrn);
  return finish(lines);
}

// Withdrawals: assumed to look like a card purchase. Anything that does not match falls through to the raw capture below.
if (type === 'V1_POS_WITHDRAWAL_TRANSACTION' && t.transactionStatus === 'SUCCESSFUL' && t.responseCode === '00') {
  const rrn = String(t.retrievalReferenceNumber || '').replace(/^0+/, '');
  const lines = ['✅ *Card withdrawal approved*', '', '*₦' + naira(t.amount) + '* withdrawal was approved on your terminal.'];
  const when = clock(t.transactionTime);
  if (when) lines.push('Time: ' + when);
  if (rrn) lines.push('Ref: ' + rrn);
  return finish(lines);
}

// Any other event type: send the raw event so we can learn its shape
const raw = 'Capture. Event: ' + type + '. Received: ' + JSON.stringify(ev).slice(0, 900);
return [{ json: { text: raw } }];
